'use client';

import Link from 'next/link';
import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { ArrowUpRight, BookOpen, ChartNoAxesColumnIncreasing, ClipboardList, LoaderCircle } from 'lucide-react';
import {
  getApiErrorMessage,
  getStudentCourses,
  getStudentExercises,
  getStudentGrades,
  getStudentProfile,
  type StudentProfile,
} from '@/lib/student-api';

export default function StudentPage() {
	const [profile, setProfile] = useState<StudentProfile | null>(null);
	const [courseCount, setCourseCount] = useState(0);
	const [exerciseCount, setExerciseCount] = useState(0);
	const [gradedCount, setGradedCount] = useState(0);
	const [loading, setLoading] = useState(true);
	const [error, setError] = useState('');
	const [attempt, setAttempt] = useState(0);

	useEffect(() => {
		const controller = new AbortController();
		setLoading(true);
		setError('');
		Promise.all([
			getStudentProfile(controller.signal),
			getStudentCourses(controller.signal),
			getStudentExercises(controller.signal),
			getStudentGrades(controller.signal),
		])
			.then(([student, courses, exercises, grades]) => {
				setProfile(student);
				setCourseCount(courses.length);
				setExerciseCount(exercises.length);
				setGradedCount(grades.length);
			})
			.catch((requestError: unknown) => {
				if (!controller.signal.aborted) {
					setError(getApiErrorMessage(requestError, 'Your dashboard could not be loaded.'));
				}
			})
			.finally(() => {
				if (!controller.signal.aborted) setLoading(false);
			});
		return () => controller.abort();
	}, [attempt]);

	const destinations = [
		{ href: '/student/courses', label: 'Your courses', description: 'Open classes and learning materials.', icon: BookOpen },
		{ href: '/student/exercises', label: 'Coursework', description: 'Upload work for your assigned exercises.', icon: ClipboardList },
		{ href: '/student/grades', label: 'Progress', description: 'Review graded work and score history.', icon: ChartNoAxesColumnIncreasing },
	];

	return (
		<section>
			<motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="relative overflow-hidden rounded-lg border border-[#c6a96b]/20 bg-[radial-gradient(ellipse_at_top_right,rgba(198,169,107,0.12),transparent_55%),linear-gradient(125deg,#151411,#0c0c0c_60%)] p-5 sm:p-8">
				<div className="relative z-10 max-w-xl">
					<p className="mb-3 text-[10px] font-semibold tracking-[0.2em] text-[#d5ba7a]">YOUR LEARNING SPACE</p>
					{loading ? (
						<div role="status" className="flex items-center gap-2 py-2 text-sm text-white/55"><LoaderCircle size={16} className="animate-spin text-[#c6a96b]" />Loading your dashboard</div>
					) : error ? (
						<div role="alert">
							<h1 className="text-xl font-semibold text-white">Dashboard unavailable</h1>
							<p className="mt-2 text-sm text-rose-200">{error}</p>
							<button onClick={() => setAttempt((value) => value + 1)} className="mt-4 min-h-10 text-sm font-medium text-[#dfc27e] underline underline-offset-4">Try again</button>
						</div>
					) : (
						<>
							<h1 className="break-words text-2xl font-semibold tracking-tight text-white sm:text-3xl">Welcome back, {profile?.full_name.split(' ')[0]}</h1>
							<p className="mt-3 max-w-md text-sm leading-6 text-white/55">Pick up where you left off and keep your learning moving forward.</p>
						</>
					)}
				</div>
			</motion.div>

			{!loading && !error && (
				<motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.08 }} className="mt-4 grid grid-cols-3 divide-x divide-white/10 rounded-lg border border-white/10 bg-white/[0.025] py-4">
					{[
						{ label: 'Courses', value: courseCount },
						{ label: 'Exercises', value: exerciseCount },
						{ label: 'Graded', value: gradedCount },
					].map((stat) => (
						<div key={stat.label} className="px-3 text-center sm:px-5">
							<p className="text-xl font-semibold tabular-nums text-white">{stat.value}</p>
							<p className="mt-1 text-[10px] text-white/45 sm:text-xs">{stat.label}</p>
						</div>
					))}
				</motion.div>
			)}

			<div className="mt-8">
				<div className="mb-3 flex items-end justify-between">
					<div>
						<p className="text-[10px] font-semibold tracking-[0.18em] text-[#c6a96b]">QUICK ACCESS</p>
						<h2 className="mt-1 text-base font-semibold text-white">Your workspace</h2>
					</div>
				</div>
				<div className="divide-y divide-white/[0.08] rounded-lg border border-white/10 bg-white/[0.02] px-4 sm:px-5">
					{destinations.map(({ href, label, description, icon: Icon }, index) => (
						<motion.div key={href} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: index * 0.05 }}>
							<Link href={href} className="group flex min-h-[76px] items-center gap-3 py-3">
								<span className="flex size-10 shrink-0 items-center justify-center rounded-lg border border-[#c6a96b]/20 bg-[#c6a96b]/[0.06] text-[#d5ba7a]"><Icon size={18} strokeWidth={1.7} /></span>
								<span className="min-w-0 flex-1">
									<span className="block text-sm font-medium text-white">{label}</span>
									<span className="mt-1 block text-xs leading-5 text-white/45">{description}</span>
								</span>
								<ArrowUpRight size={17} className="shrink-0 text-white/35 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-[#dfc27e]" />
							</Link>
						</motion.div>
					))}
				</div>
			</div>
		</section>
	);
}
